(function() {
var EMBEDDED_SAMPLES = {
  "102": "",
  "108": "",
  "24": "",
  "30": "",
  "36": "",
  "42": "",
  "48": "",
  "54": "",
  "60": "",
  "66": "",
  "72": "",
  "78": "",
  "84": "",
  "90": "",
  "96": "",
};


  class EnhancedMusic {
    constructor() {
      this.audioContext = null;
      this.masterGain = null;
      this.melodyBanks = new Map();
      this.drumSamples = new Map();
      this.currentInstrument = 1;
      this.volume = 1;
      this.sustain = false;
      this.sustainPressTime = 1;
      this.sustainReleaseTime = 0.5;
      this.bpm = 120;
      this.activeNotes = new Map();
      this.sustainedNotes = [];
      this.nextNoteId = 0;
      this._autoCycleTimer = null;
      this._stopHookInstalled = false;
      this._schedLead = 0.05;   // 音频网格前瞻量（秒）：脚本比音频提前运行的时间
      this.melodyPackName = '内置钢琴';
      this.drumPackName = '未加载';
      this.melodyLoaded = false;
      this.drumLoaded = false;
      this._ctxReady = false;

      this._drumMap = {
        '(36) 大鼓': 36,
        '(38) 小鼓': 38,
        '(42) 踩镲闭': 42,
        '(46) 踩镲开': 46,
        '(49) Crash镲': 49
      };
      this._audioExts = ['.ogg', '.mp3', '.wav'];

      this._freqTable = new Array(128);
      for (var i = 0; i < 128; i++) {
        this._freqTable[i] = 440 * Math.pow(2, (i - 69) / 12);
      }
      this._loadEmbeddedSamples();

      // 暴露实例，供钢琴预览等外部逻辑访问
      if (typeof window !== 'undefined') window.__enhancedMusicInstance = this;
    }

    _loadEmbeddedSamples() {
      var self = this;
      var keys = Object.keys(EMBEDDED_SAMPLES);
      if (keys.length === 0) return;

      var tryLoad = function() {
        try {
          var ctx = self._ensureAudioContext();
          if (ctx.state === 'suspended') {
            setTimeout(tryLoad, 500);
            return;
          }
          var pending = keys.length;
          keys.forEach(function(midiStr) {
            var midi = parseInt(midiStr, 10);
            var b64 = EMBEDDED_SAMPLES[midiStr];
            try {
              var binary = atob(b64);
              var len = binary.length;
              var bytes = new Uint8Array(len);
              for (var i = 0; i < len; i++) {
                bytes[i] = binary.charCodeAt(i);
              }
              ctx.decodeAudioData(bytes.buffer, function(buffer) {
                var bank = self.melodyBanks.get(1);
                if (!bank) {
                  bank = new Map();
                  self.melodyBanks.set(1, bank);
                }
                bank.set(midi, buffer);
                pending--;
                if (pending <= 0) {
                  self.melodyLoaded = true;
                  console.log('[增强音乐] 内置钢琴采样加载完成（乐器编号1）');
                }
              }, function(err) {
                pending--;
                console.warn('[增强音乐] 内置采样解码失败:', midiStr, err);
              });
            } catch (e) {
              pending--;
              console.warn('[增强音乐] 内置采样解析失败:', midiStr, e);
            }
          });
        } catch (e) {
          setTimeout(tryLoad, 500);
        }
      };

      tryLoad();
    }

    getInfo() {
      return {
        id: 'enhancedMusic',
        name: '增强音乐',
        color1: '#6C5CE7',
        color2: '#00B4D8',
        blocks: [
          {
            opcode: 'loadMelodySamples',
            blockType: Scratch.BlockType.COMMAND,
            text: '加载旋律音色 乐器编号 [INSTRUMENT]',
            arguments: {
              INSTRUMENT: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 1
              }
            }
          },
          {
            opcode: 'loadDrumSamples',
            blockType: Scratch.BlockType.COMMAND,
            text: '加载鼓组音色',
            arguments: {}
          },
          {
            opcode: 'setInstrument',
            blockType: Scratch.BlockType.COMMAND,
            text: '设定乐器为 [INSTRUMENT]',
            arguments: {
              INSTRUMENT: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 1
              }
            }
          },
          {
            opcode: 'playNote',
            blockType: Scratch.BlockType.COMMAND,
            text: '演奏音符 [NOTE] [DURATION] 拍',
            arguments: {
              NOTE: {
                type: Scratch.ArgumentType.NOTE,
                defaultValue: 60
              },
              DURATION: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 0.5
              }
            }
          },
          {
            opcode: 'playNoteVel',
            blockType: Scratch.BlockType.COMMAND,
            text: '演奏音符 [NOTE] [DURATION] 拍 力度 [VELOCITY]',
            arguments: {
              NOTE: {
                type: Scratch.ArgumentType.NOTE,
                defaultValue: 60
              },
              DURATION: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 0.5
              },
              VELOCITY: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 64
              }
            }
          },
          {
            opcode: 'playDrum',
            blockType: Scratch.BlockType.COMMAND,
            text: '演奏拍鼓 [DRUM] [DURATION] 拍',
            arguments: {
              DRUM: {
                type: Scratch.ArgumentType.STRING,
                menu: 'drumMenu',
                defaultValue: '(36) 大鼓'
              },
              DURATION: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 0.25
              }
            }
          },
          {
            opcode: 'rest',
            blockType: Scratch.BlockType.COMMAND,
            text: '休止 [DURATION] 拍',
            arguments: {
              DURATION: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 0.5
              }
            }
          },
          {
            opcode: 'stopAll',
            blockType: Scratch.BlockType.COMMAND,
            text: '停止所有音符',
            arguments: {}
          },
          {
            opcode: 'setSustain',
            blockType: Scratch.BlockType.COMMAND,
            text: '延音踏板 [STATE]',
            arguments: {
              STATE: {
                type: Scratch.ArgumentType.STRING,
                menu: 'sustainMenu',
                defaultValue: '抬起'
              }
            }
          },
          {
            opcode: 'autoSustainCycle',
            blockType: Scratch.BlockType.COMMAND,
            text: '每 [BEATS] 拍自动松踩踏板（0 关闭）',
            arguments: {
              BEATS: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 4
              }
            }
          },
          {
            opcode: 'setSustainTime',
            blockType: Scratch.BlockType.COMMAND,
            text: '设置延音 [MODE] 时长为 [SEC] 秒',
            arguments: {
              MODE: {
                type: Scratch.ArgumentType.STRING,
                menu: 'sustainTimeMenu',
                defaultValue: '抬起时长'
              },
              SEC: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 0.5
              }
            }
          },
          {
            opcode: 'setVolume',
            blockType: Scratch.BlockType.COMMAND,
            text: '设定音量为 [VOL] %',
            arguments: {
              VOL: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 100
              }
            }
          },
          {
            opcode: 'changeVolume',
            blockType: Scratch.BlockType.COMMAND,
            text: '将音量增加 [DELTA] %',
            arguments: {
              DELTA: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: -10
              }
            }
          },
          {
            opcode: 'setDefaultVolume',
            blockType: Scratch.BlockType.COMMAND,
            text: '设定默认音量为 [VOL] %',
            arguments: {
              VOL: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 100
              }
            }
          },
          {
            opcode: 'setTempo',
            blockType: Scratch.BlockType.COMMAND,
            text: '设定速度为 [BPM] BPM',
            arguments: {
              BPM: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 120
              }
            }
          },
          {
            opcode: 'changeTempo',
            blockType: Scratch.BlockType.COMMAND,
            text: '将速度增加 [DELTA]',
            arguments: {
              DELTA: {
                type: Scratch.ArgumentType.NUMBER,
                defaultValue: 20
              }
            }
          },
          {
            opcode: 'getSustainState',
            blockType: Scratch.BlockType.REPORTER,
            text: '踏板状态',
            arguments: {}
          },
          {
            opcode: 'getMelodyPackName',
            blockType: Scratch.BlockType.REPORTER,
            text: '当前旋律音色名称',
            arguments: {}
          },
          {
            opcode: 'getDrumPackName',
            blockType: Scratch.BlockType.REPORTER,
            text: '当前鼓组音色名称',
            arguments: {}
          }
        ],
        menus: {
          sustainMenu: {
            acceptReporters: true,
            items: ['按下', '抬起']
          },
          sustainTimeMenu: {
            acceptReporters: true,
            items: ['抬起时长', '按下时长']
          },
          drumMenu: {
            acceptReporters: true,
            items: ['(36) 大鼓', '(38) 小鼓', '(42) 踩镲闭', '(46) 踩镲开', '(49) Crash镲']
          }
        }
      };
    }

    _clamp(value, min, max) {
      return value < min ? min : value > max ? max : value;
    }

    _ensureAudioContext() {
      if (this._ctxReady) {
        if (this.audioContext.state === 'suspended') {
          this.audioContext.resume();
        }
        return this.audioContext;
      }
      if (!this.audioContext) {
        this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      }
      if (!this.masterGain) {
        this.masterGain = this.audioContext.createGain();
        this.masterGain.gain.value = this.volume;
        this.masterGain.connect(this.audioContext.destination);
      }
      if (this.audioContext.state === 'suspended') {
        this.audioContext.resume();
      }
      this._ctxReady = true;
      return this.audioContext;
    }

    _midiToFrequency(midi) {
      return this._freqTable[midi] || 440;
    }

    _beatsToSeconds(beats) {
      return beats * (60 / this.bpm);
    }

    // --- 音频网格排程 ---
    // 每个脚本在线程栈帧上维护一条"排程时间线"(_schedNext)，以音频时钟为准。
    // 阻塞积木提前 _schedLead 返回，下一块有充裕时间把音频排到精确的未来时刻，
    // 音符间隔因此不受帧率量化影响（采样级精确）。

    _gridStart(util, now) {
      var s = util.stackFrame._schedNext;
      if (typeof s !== 'number' || s < now + 0.005) {
        s = now + 0.03;   // 网格缺失或已落后（长时间停顿等）→ 重锚
      }
      return s;
    }

    // 推进网格并返回脚本侧应等待的秒数（提前 _schedLead 返回）
    _gridWait(util, s, dur) {
      util.stackFrame._schedNext = s + dur;
      var w = (s - this.audioContext.currentTime) + dur - this._schedLead;
      return w > 0.005 ? w : 0.005;
    }

    // --- Unified blocking helper (auto native yield or Promise fallback) ---

    _ensureInit(util) {
      if (util._nativeMode === undefined) {
        util._nativeMode = (typeof util.yield === 'function');
      }
      return util._nativeMode;
    }

    // Promise-based precise wait (fallback)
    _waitPromise(seconds) {
      var ms = seconds * 1000;
      if (ms <= 0) return Promise.resolve();
      return new Promise(function(resolve) {
        var deadline = performance.now() + ms;
        function check() {
          var r = deadline - performance.now();
          if (r <= 0) { resolve(); return; }
          if (r <= 4) { while (performance.now() < deadline) {} resolve(); return; }
          setTimeout(check, r - 4);
        }
        setTimeout(check, ms > 4 ? ms - 4 : 0);
      });
    }

    // Blocks the thread for `seconds`. In native mode uses util.yield() frame
    // polling; in Promise mode returns a Promise. Returns truthy if still waiting.
    _block(util, seconds) {
      var sf = util.stackFrame;
      if (!sf._tStart) {
        sf._tStart = performance.now();
        sf._tDur = seconds;
        if (!this._ensureInit(util)) return this._waitPromise(seconds);
        util.yield();
        return 1;
      }
      var elapsed = (performance.now() - sf._tStart) / 1000;
      if (elapsed < sf._tDur) {
        util.yield();
        return 1;
      }
      delete sf._tStart;
      delete sf._tDur;
      return 0;
    }

    // --- Audio helpers ---

    _stopNoteEntry(entry) {
      var now = this.audioContext.currentTime;
      try {
        entry.gain.gain.linearRampToValueAtTime(0, now + 0.5);
        entry.source.stop(now + 0.55);
      } catch (e) { /* ignore */ }
      this.activeNotes.delete(entry.noteId);
    }

    _openFolderDialog() {
      return new Promise((resolve) => {
        var input = document.createElement('input');
        input.type = 'file';
        input.webkitdirectory = true;
        input.style.display = 'none';
        document.body.appendChild(input);
        input.onchange = function(e) {
          var files = Array.from(e.target.files || []);
          document.body.removeChild(input);
          resolve(files);
        };
        input.oncancel = function() {
          document.body.removeChild(input);
          resolve([]);
        };
        var cleanup = function() {
          setTimeout(function() {
            if (document.body.contains(input)) {
              document.body.removeChild(input);
              resolve([]);
            }
          }, 1000);
        };
        window.addEventListener('focus', cleanup, { once: true });
        input.click();
      });
    }

    async _loadSamplesFromFiles(files, targetMap, label) {
      if (!this.audioContext) {
        this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
      }
      var exts = this._audioExts;
      var loadedCount = 0;
      var skippedCount = 0;

      for (var i = 0; i < files.length; i++) {
        var file = files[i];
        var fileName = file.name;
        var dotIdx = fileName.lastIndexOf('.');
        if (dotIdx < 0) continue;
        var ext = fileName.substring(dotIdx).toLowerCase();
        if (!exts.includes(ext)) continue;

        var baseName = fileName.substring(0, dotIdx);
        var midiNumber = parseInt(baseName, 10);
        if (isNaN(midiNumber)) {
          console.warn(label + ': 文件名无法解析为 MIDI 编号:', fileName);
          skippedCount++;
          continue;
        }

        try {
          var arrayBuffer = await file.arrayBuffer();
          var audioBuffer = await this.audioContext.decodeAudioData(arrayBuffer);
          targetMap.set(midiNumber, audioBuffer);
          loadedCount++;
        } catch (err) {
          console.warn(label + ': 解码失败:', fileName, err);
          skippedCount++;
        }
      }

      console.log(label + ' 加载完成:', loadedCount, '个采样,', '跳过', skippedCount, '个');
      return loadedCount;
    }

    _getBestSample(targetMap, midiNote) {
      if (targetMap.size === 0) return null;
      if (targetMap.has(midiNote)) {
        return { buffer: targetMap.get(midiNote), baseMidi: midiNote };
      }
      var bestKey = -Infinity;
      var keys = targetMap.keys();
      for (var key = keys.next(); !key.done; key = keys.next()) {
        var k = key.value;
        if (k <= midiNote && k > bestKey) bestKey = k;
      }
      if (bestKey === -Infinity) {
        keys = targetMap.keys();
        bestKey = keys.next().value;
        for (key = keys.next(); !key.done; key = keys.next()) {
          if (key.value < bestKey) bestKey = key.value;
        }
      }
      return { buffer: targetMap.get(bestKey), baseMidi: bestKey };
    }

    async loadMelodySamples(args, util) {
      var files = await this._openFolderDialog();
      if (files.length === 0) {
        console.log('加载旋律音色: 用户取消选择');
        return;
      }
      var bank = new Map();
      var count = await this._loadSamplesFromFiles(files, bank, '旋律音色');
      if (count > 0) {
        var instId = this._clamp(Math.round(args.INSTRUMENT), 1, 128);
        this.melodyBanks.set(instId, bank);
        this.melodyLoaded = true;
        console.log('旋律音色已存入乐器槽位:', instId);
        var melodyFolder = files[0].webkitRelativePath.split('/')[0];
        this.melodyPackName = melodyFolder;
        console.log('旋律音色包:', melodyFolder);
      } else {
        console.warn('加载旋律音色: 所选文件夹中没有有效的音频文件');
      }
    }

    async loadDrumSamples(args, util) {
      var files = await this._openFolderDialog();
      if (files.length === 0) {
        console.log('加载鼓组音色: 用户取消选择');
        return;
      }
      this.drumSamples.clear();
      var count = await this._loadSamplesFromFiles(files, this.drumSamples, '鼓组音色');
      if (count > 0) {
        this.drumLoaded = true;
        var drumFolder = files[0].webkitRelativePath.split('/')[0];
        this.drumPackName = drumFolder;
        console.log('鼓组音色包:', drumFolder);
      } else {
        console.warn('加载鼓组音色: 所选文件夹中没有有效的音频文件');
      }
    }

    setInstrument(args, util) {
      this.currentInstrument = this._clamp(Math.round(args.INSTRUMENT), 1, 128);
    }

    // --- Blocking blocks (native stack-timer pattern, no Promises) ---

    playNote(args, util) {
      var self = this;
      var sf = util.stackFrame;
      if (!sf._tStart) {
        var ctx = this._ensureAudioContext();
        var note = this._clamp(Math.round(args.NOTE), 0, 127);
        var dur = this._clamp(args.DURATION, 0.01, 100);
        var durationSec = this._beatsToSeconds(dur);
        var now = ctx.currentTime;
        var startAt = this._gridStart(util, now);        // 精确音频起点（网格）
        var endAt = startAt + durationSec;               // 精确音频终点
        var waitSec = this._gridWait(util, startAt, durationSec);

        var currentBank = this.melodyBanks.get(this.currentInstrument);
        var sample = currentBank ? this._getBestSample(currentBank, note) : null;

        var source, gain;
        if (sample && sample.buffer) {
          source = ctx.createBufferSource();
          source.buffer = sample.buffer;
          if (sample.baseMidi !== note) {
            source.playbackRate.value = Math.pow(2, (note - sample.baseMidi) / 12);
          }
          gain = ctx.createGain();
          source.connect(gain);
          gain.connect(this.masterGain);
        } else {
          if (!currentBank || currentBank.size === 0) {
            console.warn('当前乐器槽位无采样，使用振荡器回退，音符:', note, '乐器:', this.currentInstrument);
          }
          source = ctx.createOscillator();
          source.type = 'triangle';
          source.frequency.value = this._freqTable[note];
          gain = ctx.createGain();
          source.connect(gain);
          gain.connect(this.masterGain);
        }

        var vol = this._readThreadVolume(util);
        gain.gain.setValueAtTime(0.001, startAt);
        gain.gain.linearRampToValueAtTime(vol, startAt + 0.015);
        source.start(startAt);

        var noteId = this.nextNoteId++;
        var entry = { source: source, gain: gain, noteId: noteId, note: note, _startedAt: startAt, _schedEnd: endAt };
        this.activeNotes.set(noteId, entry);

        var isSus = this.sustain;
        if (isSus) {
          entry._sus = true;
        } else {
          var rel = endAt - 0.05;
          if (rel < startAt) rel = startAt;
          gain.gain.setValueAtTime(vol, rel);
          gain.gain.linearRampToValueAtTime(0, endAt + 0.5);
          source.stop(endAt + 0.55);
        }

        // 完成回调：闭包引用，两种阻塞模式（原生 yield / Promise 降级）通用
        var finish = function() {
          self.activeNotes.delete(entry.noteId);
          if (isSus && !entry._damped) {
            // 衰减锚定在网格终点（写定拍数结束时刻），不受脚本提前返回影响
            var sn = (typeof entry._schedEnd === 'number' &&
                      entry._schedEnd > self.audioContext.currentTime)
              ? entry._schedEnd
              : self.audioContext.currentTime;
            if (self.sustain) {
              // 琴键松开时踏板仍按住：进入挂起池，靠踏板延音。
              // 指数慢尾（先快后慢，钢琴弦形态）+ 音高相关（低音悠长、高音清脆）
              var decayScale = Math.pow(2, (entry.note - 60) / 24);
              var t = self.sustainPressTime / decayScale;
              if (t < 0.15) t = 0.15;
              if (t > 15) t = 15;
              try {
                entry.gain.gain.setValueAtTime(entry.gain.gain.value || 0.001, sn);
                entry.gain.gain.setTargetAtTime(0, sn, t / 3);
                entry.source.stop(sn + t * 1.2 + 0.1);   // 安全上限：必定终止（含振荡器回退）
              } catch (e) {}
              self.sustainedNotes.push(entry);
            } else {
              // 琴键松开时踏板已抬起：无制音器托底，直接快速释放
              var rt = self.sustainReleaseTime;
              try {
                entry.gain.gain.setValueAtTime(entry.gain.gain.value || 0.001, sn);
                entry.gain.gain.setTargetAtTime(0, sn, rt / 4);
                entry.source.stop(sn + rt + 0.1);
              } catch (e) {}
            }
          }
          delete sf._finish;
          delete sf._durationSec;
        };
        sf._finish = finish;
        sf._durationSec = waitSec;

        var r = this._block(util, waitSec);
        if (r && typeof r.then === 'function') return r.then(finish);
        if (r) return;
        finish();
        return;
      }

      if (this._block(util, sf._durationSec)) return;
      if (sf._finish) sf._finish();
    }

    playNoteVel(args, util) {
      var self = this;
      var sf = util.stackFrame;
      if (!sf._tStart) {
        var ctx = this._ensureAudioContext();
        var note = this._clamp(Math.round(args.NOTE), 0, 127);
        var dur = this._clamp(args.DURATION, 0.01, 100);
        var velocity = this._clamp(Math.round(args.VELOCITY), 0, 127);
        // 力度→增益：平方曲线（MIDI 惯例的近似感知映射），与脚本级音量相乘
        var velFactor = Math.pow(velocity / 127, 2);
        var durationSec = this._beatsToSeconds(dur);
        var now = ctx.currentTime;
        var startAt = this._gridStart(util, now);        // 精确音频起点（网格）
        var endAt = startAt + durationSec;               // 精确音频终点
        var waitSec = this._gridWait(util, startAt, durationSec);

        var currentBank = this.melodyBanks.get(this.currentInstrument);
        var sample = currentBank ? this._getBestSample(currentBank, note) : null;

        var source, gain;
        if (sample && sample.buffer) {
          source = ctx.createBufferSource();
          source.buffer = sample.buffer;
          if (sample.baseMidi !== note) {
            source.playbackRate.value = Math.pow(2, (note - sample.baseMidi) / 12);
          }
          gain = ctx.createGain();
          source.connect(gain);
          gain.connect(this.masterGain);
        } else {
          if (!currentBank || currentBank.size === 0) {
            console.warn('当前乐器槽位无采样，使用振荡器回退，音符:', note, '乐器:', this.currentInstrument);
          }
          source = ctx.createOscillator();
          source.type = 'triangle';
          source.frequency.value = this._freqTable[note];
          gain = ctx.createGain();
          source.connect(gain);
          gain.connect(this.masterGain);
        }

        var vol = this._readThreadVolume(util) * velFactor;
        gain.gain.setValueAtTime(0.001, startAt);
        gain.gain.linearRampToValueAtTime(vol, startAt + 0.015);
        source.start(startAt);

        var noteId = this.nextNoteId++;
        var entry = { source: source, gain: gain, noteId: noteId, note: note, _startedAt: startAt, _schedEnd: endAt };
        this.activeNotes.set(noteId, entry);

        var isSus = this.sustain;
        if (isSus) {
          entry._sus = true;
        } else {
          var rel = endAt - 0.05;
          if (rel < startAt) rel = startAt;
          gain.gain.setValueAtTime(vol, rel);
          gain.gain.linearRampToValueAtTime(0, endAt + 0.5);
          source.stop(endAt + 0.55);
        }

        // 完成回调：闭包引用，两种阻塞模式（原生 yield / Promise 降级）通用
        var finish = function() {
          self.activeNotes.delete(entry.noteId);
          if (isSus && !entry._damped) {
            // 衰减锚定在网格终点（写定拍数结束时刻），不受脚本提前返回影响
            var sn = (typeof entry._schedEnd === 'number' &&
                      entry._schedEnd > self.audioContext.currentTime)
              ? entry._schedEnd
              : self.audioContext.currentTime;
            if (self.sustain) {
              // 琴键松开时踏板仍按住：进入挂起池，靠踏板延音。
              // 指数慢尾（先快后慢，钢琴弦形态）+ 音高相关（低音悠长、高音清脆）
              var decayScale = Math.pow(2, (entry.note - 60) / 24);
              var t = self.sustainPressTime / decayScale;
              if (t < 0.15) t = 0.15;
              if (t > 15) t = 15;
              try {
                entry.gain.gain.setValueAtTime(entry.gain.gain.value || 0.001, sn);
                entry.gain.gain.setTargetAtTime(0, sn, t / 3);
                entry.source.stop(sn + t * 1.2 + 0.1);   // 安全上限：必定终止（含振荡器回退）
              } catch (e) {}
              self.sustainedNotes.push(entry);
            } else {
              // 琴键松开时踏板已抬起：无制音器托底，直接快速释放
              var rt = self.sustainReleaseTime;
              try {
                entry.gain.gain.setValueAtTime(entry.gain.gain.value || 0.001, sn);
                entry.gain.gain.setTargetAtTime(0, sn, rt / 4);
                entry.source.stop(sn + rt + 0.1);
              } catch (e) {}
            }
          }
          delete sf._finish;
          delete sf._durationSec;
        };
        sf._finish = finish;
        sf._durationSec = waitSec;

        var r = this._block(util, waitSec);
        if (r && typeof r.then === 'function') return r.then(finish);
        if (r) return;
        finish();
        return;
      }

      if (this._block(util, sf._durationSec)) return;
      if (sf._finish) sf._finish();
    }

    playDrum(args, util) {
      var self = this;
      var sf = util.stackFrame;
      if (!sf._tStart) {
        this._ensureAudioContext();
        var midiNote = this._drumMap[args.DRUM] || 36;
        var sample = this._getBestSample(this.drumSamples, midiNote);

        if (!sample || !sample.buffer) {
          console.warn('鼓组音色未加载或无此采样，无法播放拍鼓:', args.DRUM);
          return;
        }

        var ctx = this.audioContext;
        var source = ctx.createBufferSource();
        source.buffer = sample.buffer;
        var gain = ctx.createGain();
        source.connect(gain);
        gain.connect(this.masterGain);

        var dur = this._clamp(args.DURATION, 0.01, 100);
        var durationSec = this._beatsToSeconds(dur);
        var now = ctx.currentTime;
        var startAt = this._gridStart(util, now);
        var endAt = startAt + durationSec;
        var waitSec = this._gridWait(util, startAt, durationSec);

        var vol = this._readThreadVolume(util);
        gain.gain.setValueAtTime(0.001, startAt);
        gain.gain.linearRampToValueAtTime(vol, startAt + 0.01);
        source.start(startAt);
        source.stop(endAt + 0.1);
        gain.gain.setValueAtTime(vol, endAt - 0.05);
        gain.gain.linearRampToValueAtTime(0, endAt + 0.06);

        var noteId = this.nextNoteId++;
        var entry = { source: source, gain: gain, noteId: noteId, note: midiNote, _schedEnd: endAt };
        this.activeNotes.set(noteId, entry);

        var finish = function() {
          self.activeNotes.delete(entry.noteId);
          delete sf._finish;
          delete sf._durationSec;
        };
        sf._finish = finish;
        sf._durationSec = waitSec;

        var r = this._block(util, waitSec);
        if (r && typeof r.then === 'function') return r.then(finish);
        if (r) return;
        finish();
        return;
      }

      if (this._block(util, sf._durationSec)) return;
      if (sf._finish) sf._finish();
    }

    rest(args, util) {
      var sf = util.stackFrame;
      if (!sf._tStart) {
        var dur = this._beatsToSeconds(this._clamp(args.DURATION, 0.01, 100));
        if (this.audioContext) {
          var s = this._gridStart(util, this.audioContext.currentTime);
          sf._durationSec = this._gridWait(util, s, dur);   // 休止同样推进网格
        } else {
          sf._durationSec = dur;
        }
      }
      return this._block(util, sf._durationSec);
    }

    stopAll(args, util) {
      var now = this.audioContext ? this.audioContext.currentTime : 0;
      var entries = this.activeNotes.values();
      for (var entry = entries.next(); !entry.done; entry = entries.next()) {
        var e = entry.value;
        e._damped = true;
        try {
          e.gain.gain.linearRampToValueAtTime(0, now + 0.05);
          e.source.stop(now + 0.06);
        } catch (ex) {}
      }
      this.activeNotes.clear();
      for (var i = 0; i < this.sustainedNotes.length; i++) {
        var s = this.sustainedNotes[i];
        s._damped = true;
        try {
          s.gain.gain.linearRampToValueAtTime(0, now + 0.05);
          s.source.stop(now + 0.06);
        } catch (ex) {}
      }
      this.sustainedNotes = [];
    }

    // 制音。minAgeSec：保护新音头（比该秒数更年轻的音符跳过制音）；
    // dampSec：本次制音时长（默认用「抬起时长」设置）
    _dampSustained(minAgeSec, dampSec) {
      var now = this.audioContext ? this.audioContext.currentTime : 0;
      var t = (dampSec !== undefined) ? dampSec : this.sustainReleaseTime;
      var minAge = minAgeSec || 0;

      // 从当前音量开始指数衰减（不跳变）；返回 false 表示被保护、未制音
      var damp = function(entry) {
        if (!entry || entry._damped) return true;
        if (minAge > 0 && typeof entry._startedAt === 'number' &&
            (now - entry._startedAt) < minAge) {
          return false;   // 音符太年轻（音头阶段），跳过，避免吞掉音头
        }
        entry._damped = true;
        var g = entry.gain.gain;
        try {
          if (typeof g.cancelAndHoldAtTime === 'function') {
            g.cancelAndHoldAtTime(now);      // 保持当前音量，避免跳变
          } else {
            g.cancelScheduledValues(now);
            g.setValueAtTime(g.value || 0.001, now);
          }
          g.setTargetAtTime(0, now, t / 4);  // 指数衰减，接近钢琴制音器手感
          entry.source.stop(now + t + 0.1);
        } catch (e) {}
        return true;
      };

      // 只制音"琴键已松开"（写定拍数已结束、靠踏板延音）的音符。
      // 仍在阻挡期内（按谱演奏中）的音符不受踏板换踩影响——
      // 真钢琴：手按住的键，制音器始终离开该弦，跨小节长音因此天然免疫。
      var survivors = [];
      for (var i = 0; i < this.sustainedNotes.length; i++) {
        if (!damp(this.sustainedNotes[i])) survivors.push(this.sustainedNotes[i]);
      }
      this.sustainedNotes = survivors;
    }

    setSustain(args, util) {
      if (args.STATE === '按下') {
        this.sustain = true;
        return;
      }
      this.sustain = false;
      this._dampSustained();
    }

    _cancelAutoCycle() {
      if (this._autoCycleTimer) {
        clearTimeout(this._autoCycleTimer);
        this._autoCycleTimer = null;
      }
    }

    autoSustainCycle(args, util) {
      var self = this;
      this._cancelAutoCycle();

      var beats = this._clamp(args.BEATS, 0, 64);
      if (beats <= 0) {
        console.log('[增强音乐] 自动松踩踏板已关闭');
        return;
      }

      // 程序结束（脚本全部结束 / 停止按钮 / 重新开始）时自动清除循环
      if (!this._stopHookInstalled && util.runtime && typeof util.runtime.on === 'function') {
        this._stopHookInstalled = true;
        util.runtime.on('PROJECT_RUN_STOP', function() { self._cancelAutoCycle(); });
        util.runtime.on('PROJECT_STOP_ALL', function() { self._cancelAutoCycle(); });
        util.runtime.on('PROJECT_START', function() { self._cancelAutoCycle(); });
      }

      var intervalMs = function() { return self._beatsToSeconds(beats) * 1000; };
      var nextAt = performance.now() + intervalMs();

      var tick = function() {
        // 漂移补偿：按绝对时间点安排下一次
        var nowMs = performance.now();
        nextAt += intervalMs();
        if (nextAt <= nowMs) nextAt = nowMs + intervalMs();
        self._autoCycleTimer = setTimeout(tick, nextAt - nowMs);

        if (!self.sustain) return;   // 踏板未按下时仅空转

        // 换踏板。所有时长按周期缩放，高 BPM 下不会出现"整段音符落在换踩间隙里"：
        //   保护窗 = 1.3×周期（留 30% 余量，避免音符出生网格压在边界上被抖动误判）
        //   制音时长 ≤ 0.15×周期（且 ≤0.1s）：换踩节奏越快，落弦越利落
        //   换踩间隙 ≤ 0.15×周期（且 ≤120ms）：间隙压缩到周期的零头
        var cycleSec = intervalMs() / 1000;
        self.sustain = false;
        self._dampSustained(
          cycleSec * 1.3,
          Math.min(self.sustainReleaseTime, 0.1, cycleSec * 0.15)
        );

        // 踩：间隙过后重新按下（循环仍激活才重踩）
        var gapMs = Math.min(120, intervalMs() * 0.15);
        setTimeout(function() {
          if (self._autoCycleTimer !== null) self.sustain = true;
        }, gapMs);
      };

      this._autoCycleTimer = setTimeout(tick, intervalMs());
      console.log('[增强音乐] 自动松踩踏板：每 ' + beats + ' 拍松踩一次');
    }

    setSustainTime(args, util) {
      var sec = this._clamp(args.SEC, 0.01, 10);
      if (args.MODE === '抬起时长') {
        this.sustainReleaseTime = sec;
      } else {
        this.sustainPressTime = sec;
      }
    }

    _readThreadVolume(util) {
      var sf = util && util.stackFrame;
      return (sf && sf._vol !== undefined) ? sf._vol : this.volume;
    }

    setVolume(args, util) {
      var v = this._clamp(args.VOL, 0, 100) / 100;
      // 写入线程级持久帧，仅影响当前脚本
      if (util && util.stackFrame) util.stackFrame._vol = v;
    }

    changeVolume(args, util) {
      var cur = this._readThreadVolume(util);
      var v = this._clamp(cur * 100 + args.DELTA, 0, 100) / 100;
      if (util && util.stackFrame) util.stackFrame._vol = v;
    }

    setDefaultVolume(args, util) {
      this.volume = this._clamp(args.VOL, 0, 100) / 100;
    }

    setTempo(args, util) {
      this.bpm = this._clamp(args.BPM, 20, 500);
    }

    changeTempo(args, util) {
      this.bpm = this._clamp(this.bpm + args.DELTA, 20, 500);
    }

    getSustainState(args, util) {
      return this.sustain ? '按下' : '抬起';
    }

    getMelodyPackName(args, util) {
      return this.melodyPackName;
    }

    getDrumPackName(args, util) {
      return this.drumPackName;
    }
  }

  function tryRegister() {
    // 环境无关注册：词法作用域 Scratch（Gandi 注入式）优先，window/self 兜底（TurboWarp 桌面端）
    var S = null;
    try { if (typeof Scratch !== 'undefined' && Scratch && Scratch.extensions) S = Scratch; } catch (e) {}
    if (!S && typeof window !== 'undefined' && window.Scratch && window.Scratch.extensions) S = window.Scratch;
    if (!S && typeof self !== 'undefined' && self.Scratch && self.Scratch.extensions) S = self.Scratch;
    if (S && typeof S.extensions.register === 'function') {
      S.extensions.register(new EnhancedMusic());
      console.log('[增强音乐] 扩展已注册');
      return true;
    }
    return false;
  }

  if (!tryRegister()) {
    var count = 0;
    var interval = setInterval(function() {
      count++;
      if (tryRegister() || count > 60) {
        clearInterval(interval);
        if (count > 60) console.error('[增强音乐] 注册超时，请检查控制台');
      }
    }, 500);
  }
})();
